note "Keys are shown once, at creation."
while :; do
  ask_secret RESEND_API_KEY "Paste the Resend API key (re_…):"
  [[ "$RESEND_API_KEY" == re_* ]] && break
  warn "Resend keys start with re_ — try again"
done
write_env RESEND_API_KEY "$RESEND_API_KEY"
vercel_env RESEND_API_KEY "$RESEND_API_KEY" --sensitive
vercel_env EMAIL_FROM "Booklo <noreply@booklo.co>"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "App settings — generated secrets and fixed values"
SCHEDULING_DRAIN_SECRET=$(_existing SCHEDULING_DRAIN_SECRET || openssl rand -hex 24)
CHASE_DRAIN_SECRET=$(_existing CHASE_DRAIN_SECRET || openssl rand -hex 24)
say "Drain secrets generated (kept in ${ENV_FILE} so you can tick reminders by hand)."
ask INTERNAL_EMAILS "Emails allowed into /utils (comma-separated) [andriishcherbiakdev@gmail.com,andriyshcherbyak@gmail.com]:"
INTERNAL_EMAILS="${INTERNAL_EMAILS:-andriishcherbiakdev@gmail.com,andriyshcherbyak@gmail.com}"
write_env SCHEDULING_DRAIN_SECRET "$SCHEDULING_DRAIN_SECRET"
write_env CHASE_DRAIN_SECRET "$CHASE_DRAIN_SECRET"
write_env INTERNAL_EMAILS "$INTERNAL_EMAILS"
vercel_env APP_ENV "production"
vercel_env NEXT_PUBLIC_APP_URL "$TEST_URL"
vercel_env SCHEDULING_DRAIN_SECRET "$SCHEDULING_DRAIN_SECRET" --sensitive
vercel_env CHASE_DRAIN_SECRET "$CHASE_DRAIN_SECRET" --sensitive
vercel_env INTERNAL_EMAILS "$INTERNAL_EMAILS"
note "(BILLING_FAKE_SECRET deliberately NOT set: src/env-schema.ts rejects it under APP_ENV=production.)"
printf '\n'; vercel env ls production 2>/dev/null | sed 's/^/  /' || true
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase — push auth config (site_url, redirects, SMTP, rate limits, templates)"
say "Pushes supabase/config.toml's [remotes.production] block to ${REF}."
warn "Overwrites the project's remote config. Review the diff the CLI shows — it covers"
