pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Database — apply migrations (session pooler)"
say "ALLOW_REMOTE_DB=1 DATABASE_URL=<session :5432> npx drizzle-kit migrate"
note "Idempotent: drizzle's journal skips what is already applied."
if confirm "Migrate ${REF} now?"; then
