    printf '\n'
    if curl -fsS "$TEST_URL/" >/dev/null; then
      printf '  %s✓ %s answers%s\n' "$GREEN" "$TEST_URL" "$RESET"
    else
      warn "$TEST_URL did not answer 200 — if it redirects to vercel.com/login, stage 1 was not applied"
    fi
    status=$(curl -sS -o /dev/null -w '%{http_code}' -X POST "$TEST_URL/api/scheduling/drain" || echo "000")
    if [[ "$status" == "401" ]]; then
      printf '  %s✓ drain route rejects anonymous calls (401) — SCHEDULING_DRAIN_SECRET is live%s\n' "$GREEN" "$RESET"
    else
      warn "POST /api/scheduling/drain returned $status (expected 401; 503 means the secret is missing)"
    fi
